import sys, collections as cc
input = sys.stdin.readline
I = lambda : list(map(int, input().split()))

def div(b):
	an = []
	for i in range(1, int(b ** 0.5) + 1):
		if b % i == 0:
			an.append(i)
			if i != b // i:
				an.append(b // i)
	return an
